const cinemas=[{name:'Starlight Kingston',place:'Kingston, Jamaica',address:'New Kingston entertainment district',img:'https://images.unsplash.com/photo-1478720568477-152d9b164e26?w=900&q=85',screens:'5 Screens'},{name:'Starlight Portmore',place:'Portmore, St. Catherine',address:'Portmore town centre',img:'https://images.unsplash.com/photo-1489599849927-2ee91cede3ba?w=900&q=85',screens:'4 Screens'},{name:'Starlight Montego Bay',place:'Montego Bay, St. James',address:'Montego Bay shopping district',img:'https://images.unsplash.com/photo-1517604931442-7e0c8ed2963c?w=900&q=85',screens:'3 Screens'}];
let fees={Adult:1800,Child:1100,Senior:1300};let state={page:'home',movie:'midnight',cinema:0,date:todayISO(),time:'6:30 PM',seats:[],ticketType:'Adult',ticketCount:1};
const movieDefaults=JSON.parse(JSON.stringify(movies));
function storageGet(key,fallback){try{let v=JSON.parse(localStorage.getItem(key));return v??fallback}catch{return fallback}}
// Admin overrides take precedence until Reset to Code Defaults is clicked.
movies=storageGet('starlightAdminMovies',movies);
let customShows=storageGet('starlightAdminShows',{});
function persistAdmin(){localStorage.setItem('starlightAdminMovies',JSON.stringify(movies));localStorage.setItem('starlightAdminShows',JSON.stringify(customShows));localStorage.setItem('starlightAdminFees',JSON.stringify(fees))}
fees=storageGet('starlightAdminFees',fees);
function showsFor(m){let v=customShows[m.id];return Array.isArray(v)?v:['1:00 PM','4:00 PM','6:30 PM','9:00 PM']}
function safePoster(v){const path=String(v||'').trim();if(!path)return '';if(/^https?:\/\//i.test(path))return safeUrl(path);if(/^(?:images\/|\.\/images\/)[a-zA-Z0-9_./%() -]+$/i.test(path)&&!path.split('/').includes('..'))return path;return ''}
function safeUrl(v){try{const u=new URL(v);return ['https:','http:'].includes(u.protocol)?u.href:''}catch{return ''}}
function trailerEmbed(u){let url=safeUrl(u);if(!url)return '';let id=url.match(/(?:youtube\.com\/(?:watch\?v=|embed\/)|youtu\.be\/)([\w-]{11})/);if(id)return 'https://www.youtube-nocookie.com/embed/'+id[1]+'?autoplay=1';let v=url.match(/vimeo\.com\/(\d+)/);return v?'https://player.vimeo.com/video/'+v[1]+'?autoplay=1':''}
function showTrailer(id){let m=movies.find(x=>x.id===id),url=trailerEmbed(m?.trailer||'');let d=document.createElement('div');d.className='video-modal';d.id='trailerModal';d.innerHTML=`<div class="video-shell" role="dialog" aria-modal="true" aria-label="Movie trailer"><div class="video-top"><h3>${esc(m?.name||'Movie')} · Trailer</h3><button onclick="closeTrailer()" aria-label="Close trailer">×</button></div>${url?`<iframe src="${esc(url)}" title="Movie trailer" allow="autoplay;encrypted-media;picture-in-picture" referrerpolicy="strict-origin-when-cross-origin" allowfullscreen></iframe>`:`<div class="empty" style="padding:65px 20px">No trailer has been added for this demo movie yet.<br><small>Open Admin → Edit Movie to add a YouTube or Vimeo link.</small></div>`}</div>`;d.onclick=e=>{if(e.target===d)closeTrailer()};document.body.append(d)}
function closeTrailer(){document.getElementById('trailerModal')?.remove()}
document.addEventListener('keydown',e=>{if(e.key==='Escape')closeTrailer()});
function todayISO(){return new Date().toLocaleDateString('en-CA')};function plusDays(n){let d=new Date();d.setDate(d.getDate()+n);return d.toLocaleDateString('en-CA')};function money(n){return 'J$'+n.toLocaleString('en-JM')};function esc(v){return String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))};function saved(){try{return JSON.parse(localStorage.getItem('starlightTickets')||'[]')}catch{return []}}function saveTickets(a){localStorage.setItem('starlightTickets',JSON.stringify(a))}function signedIn(){try{const s=JSON.parse(sessionStorage.getItem('starlightDemoSession')||'null');return s&&typeof s.email==='string'?s:null}catch{return null}}
function memberRecord(){const s=signedIn();return s?storageGet('starlightDemoAccounts',[]).find(u=>u.email===s.email):null}
function giftsSaved(){return storageGet('starlightDemoGifts',[])}
function visitDate(ticket){const d=new Date(ticket.date+'T'+(ticket.time||'12:00 PM'));if(!Number.isNaN(+d))return d;const match=(ticket.time||'').match(/(\d{1,2}):(\d{2})\s*(AM|PM)/i);if(!match)return new Date(ticket.date+'T23:59:59');let h=(Number(match[1])%12)+(match[3].toUpperCase()==='PM'?12:0);return new Date(ticket.date+'T'+String(h).padStart(2,'0')+':'+match[2]+':00')}
function profileTicketRow(t){const title=movies.find(m=>m.id===t.movie)?.name||t.movie;return `<div class="summary-row"><div><strong>${esc(title)}</strong><br><span>${esc(t.date)} · ${esc(t.time)} · ${esc(cinemas[t.cinema]?.name||'Cinema')}</span><br><small>Seats: ${esc(t.seats.join(', '))} · ${money(t.total)}</small></div><button class="btn btn-sm btn-ghost" onclick="state.lastTicket='${esc(t.code)}';navigate('confirmation')">VIEW</button></div>`}
function giftRow(g){return `<div class="summary-row"><div><strong>${money(g.amount)} · ${esc(g.recipient)}</strong><br><span>${esc(g.email)} · ${new Date(g.created).toLocaleDateString()}</span><br><small>${esc(g.code)} · ${g.redeemed?'Marked redeemed (demo)':'Saved demo e-gift'}</small></div>${g.redeemed?'':`<button class="btn btn-sm btn-ghost" onclick="redeemDemoGift('${esc(g.code)}')">MARK REDEEMED</button>`}</div>`}
function redeemDemoGift(code){const s=signedIn();if(!s){location.href='login.html';return}const all=giftsSaved();const g=all.find(g=>g.code===code&&g.owner===s.email);if(!g)return;g.redeemed=true;g.redeemedAt=new Date().toISOString();localStorage.setItem('starlightDemoGifts',JSON.stringify(all));toast('Demo gift marked redeemed');render()}
function logoutMember(){sessionStorage.removeItem('starlightDemoSession');location.href='login.html'}
function toast(s){document.querySelector('.toast')?.remove();let d=document.createElement('div');d.className='toast';d.textContent=s;document.body.append(d);setTimeout(()=>d.remove(),3500)}
const hero=(heading,text)=>`<section class="page-hero"><div class="wrap"><div class="eyebrow">★ YOUR STARRING MOMENT</div><h1>${heading}</h1><p>${text}</p></div></section>`;
const poster=m=>`<div class="poster" style="background-color:${esc(m.color||'#182033')};background-image:url(&quot;${esc(safePoster(m.poster))}&quot;)"><span class="pill">${m.badge}</span><div class="poster-content"><div class="poster-kicker">${m.tag}</div><div class="poster-title">${m.name}</div></div></div>`;
const movieCard=m=>`<article class="movie col-6 col-md-4 col-xl-3">${poster(m)}<h3>${esc(m.name)}</h3><div class="movie-meta"><b>★ FEATURED</b> · ${esc(m.genre)} · ${esc(m.runtime)}</div><div class="movie-actions"><button class="btn" onclick="bookMovie('${m.id}')">BOOK NOW →</button><button class="btn btn-outline" onclick="showTrailer('${m.id}')">▶ TRAILER</button><button type="button" class="btn btn-outline movie-details" data-movie-id="${esc(m.id)}">DETAILS</button></div></article>`;
function home(){return `<section class="hero"><div class="wrap hero-inner"><div class="eyebrow">THE BIG SCREEN IS CALLING</div><h1>MORE THAN<br>A <em>MOVIE.</em><br>AN EXPERIENCE.</h1><p>Unforgettable stories. Premium screens. The best seats in Jamaica. Your next movie night starts right here.</p><div class="hero-actions"><a class="btn" href="#schedule">🎟 EXPLORE SHOWTIMES →</a><a class="btn btn-outline" href="#cinemas">OUR CINEMAS</a></div><div class="hero-foot"><span><b>★</b> Premium movie experiences</span><span><b>✓</b> Easy online booking</span></div></div></section><div class="wrap"><div class="statbar"><div class="stat"><div class="stat-icon">🎬</div><div><strong>Fresh releases</strong><span>Stories worth seeing on the big screen</span></div></div><div class="stat"><div class="stat-icon">📍</div><div><strong>Across Jamaica</strong><span>Discover your nearest cinema</span></div></div><div class="stat"><div class="stat-icon">🎟</div><div><strong>Book in seconds</strong><span>Choose your show and favorite seats</span></div></div></div></div><section class="trailer-section"><div class="wrap"><button class="trailer-play" aria-label="Play featured movie trailer" onclick="showTrailer(movies[0]?.id)">▶</button><div class="eyebrow">NOW PLAYING · EXPERIENCE CINEMA</div><h2>EVERY GREAT STORY DESERVES A BIG SCREEN.</h2><p>Watch previews, pick a showtime, and discover your next unforgettable movie night.</p><button class="btn btn-outline" onclick="showTrailer(movies[0]?.id)">▶ WATCH FEATURED TRAILER</button></div></section><section class="section"><div class="wrap"><div class="section-top"><div><div class="eyebrow">LIGHTS. CAMERA. ACTION.</div><h2>Now Showing</h2><p class="sub">Find your next must-see movie.</p></div><a class="btn btn-ghost" href="#movies">VIEW ALL MOVIES →</a></div><div class="movie-grid row g-4">${movies.slice(0,4).map(movieCard).join('')}</div></div></section><section class="section tight"><div class="wrap"><div class="banner"><div><div class="eyebrow">THE PERFECT PRESENT</div><h2>Give them a ticket to unforgettable.</h2><p>Treat someone special to a night at the movies with a Starlight e-gift card.</p><a class="btn" href="#gifts">EXPLORE E-GIFTS →</a></div><div class="gift-visual">🎁</div></div></div></section><section class="section"><div class="wrap"><div class="section-top"><div><div class="eyebrow">RIGHT AROUND THE CORNER</div><h2>Find Your Cinema</h2></div><a class="btn btn-ghost" href="#cinemas">ALL LOCATIONS →</a></div><div class="location-grid">${locationCards()}</div></div></section>`}
// Cinematic discovery controls 
const discovery={query:'',genre:'all',rating:'all',sort:'featured'};
function movieGenres(){return [...new Set(movies.flatMap(m=>String(m.genre||'').split('/').map(g=>g.trim()).filter(Boolean)))].sort()}
function moviesPage(){return hero('Discover your next movie','Explore our sample cinema lineup and find the perfect big-screen experience.')+`<section class="section"><div class="wrap"><div class="section-top"><div><div class="eyebrow">★ CURATED FOR MOVIE LOVERS</div><h2>Now Showing</h2><p class="sub">Search and filter the lineup. All films and showtimes are illustrative.</p></div></div><div class="discovery-panel"><div class="discovery-search"><label for="discoverQuery">SEARCH MOVIES</label><input id="discoverQuery" class="form-control" type="search" placeholder="Search by title, genre or description…" value="${esc(discovery.query)}"  autocomplete="off"></div><div class="discovery-field"><label for="discoverGenre">GENRE</label><select id="discoverGenre" class="form-select" onchange="updateDiscovery('genre',this.value)"><option value="all">All genres</option>${movieGenres().map(g=>`<option value="${esc(g)}" ${discovery.genre===g?'selected':''}>${esc(g)}</option>`).join('')}</select></div><div class="discovery-field"><label for="discoverRating">AGE RATING</label><select id="discoverRating" class="form-select" onchange="updateDiscovery('rating',this.value)"><option value="all">Any rating</option>${[...new Set(movies.map(m=>m.rating).filter(Boolean))].sort().map(r=>`<option value="${esc(r)}" ${discovery.rating===r?'selected':''}>${esc(r)}</option>`).join('')}</select></div><div class="discovery-field"><label for="discoverSort">SORT BY</label><select id="discoverSort" class="form-select" onchange="updateDiscovery('sort',this.value)"><option value="featured" ${discovery.sort==='featured'?'selected':''}>Featured</option><option value="az" ${discovery.sort==='az'?'selected':''}>Title A–Z</option><option value="za" ${discovery.sort==='za'?'selected':''}>Title Z–A</option><option value="short" ${discovery.sort==='short'?'selected':''}>Shortest first</option></select></div><div class="discovery-actions"><button class="btn btn-outline btn-sm" onclick="resetDiscovery()">RESET FILTERS</button></div></div><div class="discovery-results"><p id="discoverCount" aria-live="polite"></p></div><div id="moviesGrid" class="movie-grid row g-4"></div></div></section>`}
function durationMinutes(m){const v=String(m.runtime||'');const h=+(v.match(/(\d+)h/)||[])[1]||0;const mins=+(v.match(/(\d+)m/)||[])[1]||0;return h*60+mins}
function renderDiscovery(){const grid=document.getElementById('moviesGrid');if(!grid)return;const q=discovery.query.trim().toLocaleLowerCase();let found=movies.filter(m=>(!q||[m.name,m.genre,m.desc,m.rating].join(' ').toLocaleLowerCase().includes(q))&&(discovery.genre==='all'||String(m.genre).split('/').some(g=>g.trim()===discovery.genre))&&(discovery.rating==='all'||m.rating===discovery.rating));if(discovery.sort==='az')found.sort((a,b)=>a.name.localeCompare(b.name));if(discovery.sort==='za')found.sort((a,b)=>b.name.localeCompare(a.name));if(discovery.sort==='short')found.sort((a,b)=>durationMinutes(a)-durationMinutes(b));grid.innerHTML=found.length?found.map(movieCard).join(''):'<div class="discovery-empty"><span>🎬</span><h3>No movies found</h3><p>Try a different search or clear your filters.</p><button class="btn btn-outline" onclick="resetDiscovery()">CLEAR FILTERS</button></div>';const count=document.getElementById('discoverCount');if(count)count.textContent=`Showing ${found.length} of ${movies.length} movies`;enhanceMotion(grid)}
function updateDiscovery(key,value){discovery[key]=value;renderDiscovery()}
function resetDiscovery(){discovery.query='';discovery.genre='all';discovery.rating='all';discovery.sort='featured';const app=document.getElementById('app');if(app?.dataset.initialPage==='movies'){app.innerHTML=moviesPage();renderDiscovery()}}
function filterMovies(el,genre){updateDiscovery('genre',genre)}
function dateOptions(){return Array.from({length:7},(_,i)=>`<option value="${plusDays(i)}" ${state.date===plusDays(i)?'selected':''}>${new Date(plusDays(i)+'T12:00:00').toLocaleDateString('en-US',{weekday:'short',month:'short',day:'numeric'})}</option>`).join('')}
function cinemaOptions(){return cinemas.map((c,i)=>`<option value="${i}" ${state.cinema===i?'selected':''}>${c.name}</option>`).join('')}
function schedule(){return hero('Find Your Showtime','Pick a cinema, choose a day, and grab the best seats. Movie schedules below are illustrative.')+`<section class="section"><div class="wrap"><div class="panel toolbar"><div class="field"><label>YOUR CINEMA</label><select id="cinemaFilter" onchange="state.cinema=+this.value;renderShowtimes()">${cinemaOptions()}</select></div><div class="field"><label>SELECT DATE</label><select id="dateFilter" onchange="state.date=this.value;renderShowtimes()">${dateOptions()}</select></div><div class="field"><label>MOVIE</label><select id="movieFilter" onchange="renderShowtimes()"><option value="all">All movies</option>${movies.map(m=>`<option value="${m.id}">${m.name}</option>`).join('')}</select></div></div><div id="shows">${showEntries('all')}</div></div></section>`}
function showEntries(id){return movies.filter(m=>id==='all'||m.id===id).map((m,i)=>`<div class="show-card"><div class="thumb" style="background-image:url('${m.poster}')"></div><div><div class="tag">${m.rating} · ${m.runtime}</div><h3>${m.name}</h3><p class="sub">${m.genre} · ${cinemas[state.cinema].name}</p><div class="times">${showsFor(m).map(t=>`<button class="time" onclick="bookMovie('${m.id}','${t}')">${t} ↗</button>`).join('')}</div></div></div>`).join('')}
function renderShowtimes(){let sel=document.getElementById('movieFilter');document.getElementById('shows').innerHTML=showEntries(sel.value)}
function locationCards(){return cinemas.map((c,i)=>`<div class="panel location-card"><div class="location-cover" style="background-image:url('${c.img}')"></div><div class="location-body"><div class="tag">${c.screens} · JAMAICA</div><h3>${c.name}</h3><p>📍 ${c.address}</p><button class="btn btn-ghost" onclick="state.cinema=${i};navigate('schedule')">VIEW SHOWTIMES →</button></div></div>`).join('')}
function cinemasPage(){return hero('Our Cinemas','Find your favorite big-screen destination. These example locations demonstrate the cinema directory.')+`<section class="section"><div class="wrap"><div class="location-grid">${locationCards()}</div></div></section>`}
function prices(){return hero('Ticket Prices','Movie magic for every budget. All prices below are placeholders in Jamaican dollars.')+`<section class="section"><div class="wrap"><div class="pricing-grid">${[['Adult','Standard admission','Great for your next night out.'],['Child','Under 12 years','A big adventure for little movie lovers.'],['Senior','Ages 60+','Enjoy more of your favorite stories.']].map(([name,t,d])=>`<div class="panel price-card"><div class="eyebrow">${t}</div><h3>${name} Ticket</h3><div class="price">${money(fees[name])} <small>/ ticket</small></div><p class="sub">${d}</p><ul><li>✓ Standard 2D admission</li><li>✓ Choose your showtime</li><li>✓ Reserve your seat online</li></ul><a href="#schedule" class="btn">BOOK NOW →</a></div>`).join('')}</div><p class="notice" style="margin-top:25px">Concept prices only. Actual pricing, taxes, promotions, premium screens, and discounts would be configured by the cinema operator.</p></div></section>`}
function events(){let items=[['Private Screenings','Make your next celebration unforgettable with a cinema all to yourself.','https://images.unsplash.com/photo-1478720568477-152d9b164e26?w=700&q=85'],['Birthday Movie Nights','The perfect big-screen party for the movie lover in your life.','https://images.unsplash.com/photo-1530103862676-de8c9debad1d?w=700&q=85'],['Corporate Events','Host team nights, presentations, and unforgettable launches.','https://images.unsplash.com/photo-1511578314322-379afb476865?w=700&q=85']];return hero('Events & Experiences','Take your special occasion to the big screen. Explore group bookings and private cinema experiences.')+`<section class="section"><div class="wrap"><div class="events-grid">${items.map(x=>`<div class="panel event-card"><div class="event-img" style="background-image:url('${x[2]}')"></div><div class="event-body"><h3>${x[0]}</h3><p>${x[1]}</p><button class="btn btn-ghost" onclick="document.getElementById('eventForm').scrollIntoView({behavior:'smooth'})">ENQUIRE NOW →</button></div></div>`).join('')}</div><div class="panel" id="eventForm" style="max-width:720px;margin:40px auto 0"><h2>Plan an Event</h2><p class="sub">Sample enquiry form — details stay in this browser and are not sent to a cinema.</p><form onsubmit="event.preventDefault();toast('Demo enquiry captured. Connect an email service to send requests.');this.reset()"><div class="toolbar"><div class="field"><label>NAME</label><input required placeholder="Your name"></div><div class="field"><label>EMAIL</label><input required type="email" placeholder="you@example.com"></div></div><div class="toolbar"><div class="field"><label>EVENT TYPE</label><select><option>Private screening</option><option>Birthday party</option><option>Corporate event</option></select></div><div class="field"><label>GUEST COUNT</label><input required type="number" min="1" placeholder="e.g. 30"></div></div><button class="btn">SUBMIT ENQUIRY →</button></form></div></div></section>`}
function giftPage(){return hero('Give the Gift of Movies','Because great stories are even better when shared.')+`<section class="section"><div class="wrap two-col"><div class="panel"><div class="eyebrow">DIGITAL GIFT CARD</div><h2>Send a little movie magic.</h2><p class="sub">Choose an amount, write your message, and preview the gift. Demo purchases do not charge a card or send emails.</p><form onsubmit="giftSubmit(event)"><div class="field"><label>GIFT AMOUNT (JMD)</label><select id="giftAmount"><option value="2000">J$2,000</option><option value="5000">J$5,000</option><option value="10000">J$10,000</option><option value="15000">J$15,000</option></select></div><div class="spacer"></div><div class="field"><label>RECIPIENT'S NAME</label><input id="giftName" required placeholder="Who is it for?"></div><div class="spacer"></div><div class="field"><label>RECIPIENT EMAIL</label><input id="giftEmail" required type="email" placeholder="friend@example.com"></div><div class="spacer"></div><div class="field"><label>PERSONAL MESSAGE</label><input id="giftMessage" maxlength="160" placeholder="Enjoy the show!"></div><div class="spacer"></div><button class="btn" style="margin-top:15px;width:100%">PREVIEW E-GIFT →</button></form></div><div><div class="banner" style="display:block;text-align:center;padding:60px 24px"><div class="gift-visual">🎁</div><div class="eyebrow">STARLIGHT GIFT CARD</div><h2>For the love of movies.</h2><p>Made for movie nights, date nights, and everything in between.</p></div><div id="giftPreview"></div></div></div></section>`}
function giftSubmit(e){e.preventDefault();let name=esc(document.getElementById('giftName').value),amount=+document.getElementById('giftAmount').value,email=esc(document.getElementById('giftEmail').value),msg=esc(document.getElementById('giftMessage').value);document.getElementById('giftPreview').innerHTML=`<div class="panel" style="margin-top:20px"><div class="tag">GIFT PREVIEW (NOT SENT)</div><h3>For ${name}</h3><h2 style="color:var(--gold)">${money(amount)}</h2><p>${msg||'Enjoy the show!'}</p><p class="sub">To: ${email}</p><p class="notice">Preview only — not paid, delivered, or redeemable at a cinema.</p><button class="btn" onclick="saveDemoGift()">SAVE DEMO E-GIFT TO PROFILE →</button></div>`;toast('Gift preview created')}
function saveDemoGift(){const user=signedIn();if(!user){toast('Please log in before saving an e-gift.');return}const name=document.getElementById('giftName').value.trim(),email=document.getElementById('giftEmail').value.trim(),amount=Number(document.getElementById('giftAmount').value),message=document.getElementById('giftMessage').value.trim();if(!name||!email||!amount||!document.getElementById('giftEmail').checkValidity()){toast('Complete the recipient details first.');return}const g={code:'EG-'+crypto.randomUUID().slice(0,8).toUpperCase(),owner:user.email,recipient:name,email,amount,message,created:new Date().toISOString(),redeemed:false};localStorage.setItem('starlightDemoGifts',JSON.stringify([g,...giftsSaved()]));document.getElementById('giftPreview').innerHTML=`<div class="notice success">✓ Demo e-gift saved to your account. No payment or email delivery occurred. <a href="profile.html">View My Profile →</a></div>`;toast('Demo e-gift saved to profile')}
function booking(){let m=movies.find(x=>x.id===state.movie)||movies[0];let sold=new Set(['A3','A4','B7','C2','C3','D8','E5','F1','F2',...saved().filter(t=>t.movie===state.movie&&t.cinema===state.cinema&&t.date===state.date&&t.time===state.time).flatMap(t=>t.seats)]);let seats=Array.from({length:60},(_,i)=>{let id=String.fromCharCode(65+Math.floor(i/10))+(i%10+1);return `<button class="seat ${sold.has(id)?'taken':''} ${state.seats.includes(id)?'selected':''}" ${sold.has(id)?'disabled':''} onclick="toggleSeat('${id}')" title="Seat ${id}">${id}</button>`}).join('');return hero('Choose Your Seats','Make it your perfect movie night. Select seats to continue with a demo reservation.')+`<section class="section"><div class="wrap booking-layout"><div class="panel"><h2>${m.name}</h2><p class="sub">${cinemas[state.cinema].name} · ${state.date} · ${state.time}</p><div class="screen">SCREEN THIS WAY</div><div class="seatmap">${seats}</div><div class="legend"><span><i class="dot"></i> Available</span><span><i class="dot" style="background:var(--gold)"></i> Selected</span><span><i class="dot" style="background:#202734"></i> Unavailable</span></div></div><aside class="panel"><div class="eyebrow">YOUR BOOKING</div><h2>Order Summary</h2><div class="summary-row"><span>Movie</span><strong>${m.name}</strong></div><div class="summary-row"><span>Cinema</span><strong>${cinemas[state.cinema].name}</strong></div><div class="summary-row"><span>Showtime</span><strong>${state.date}<br>${state.time}</strong></div><div class="field" style="margin-top:17px"><label>TICKET TYPE</label><select onchange="state.ticketType=this.value;updateSummary()">${Object.keys(fees).map(t=>`<option ${state.ticketType===t?'selected':''}>${t}</option>`).join('')}</select></div><div class="summary-row"><span>Seats</span><strong id="selectedSeats">${state.seats.join(', ')||'None selected'}</strong></div><div class="summary-row"><span>Tickets</span><strong id="seatCount">${state.seats.length}</strong></div><div class="summary-row"><span>Total</span><strong id="total" class="summary-total">${money(state.seats.length*fees[state.ticketType])}</strong></div><button id="checkout" class="btn" style="width:100%;margin:20px 0 12px" onclick="checkout()" ${state.seats.length?'':'disabled'}>CONFIRM DEMO BOOKING →</button><p class="sub" style="font-size:11px">Demo checkout only. No actual inventory is held, and no payment is collected.</p></aside></div></section>`}
function toggleSeat(s){state.seats=state.seats.includes(s)?state.seats.filter(x=>x!==s):[...state.seats,s];document.querySelectorAll('.seat').forEach(x=>x.classList.toggle('selected',state.seats.includes(x.textContent)));updateSummary()}
function updateSummary(){document.getElementById('selectedSeats').textContent=state.seats.join(', ')||'None selected';document.getElementById('seatCount').textContent=state.seats.length;document.getElementById('total').textContent=money(state.seats.length*fees[state.ticketType]);document.getElementById('checkout').disabled=!state.seats.length}
function checkout(){if(!state.seats.length)return;let taken=new Set(saved().filter(t=>t.movie===state.movie&&t.cinema===state.cinema&&t.date===state.date&&t.time===state.time).flatMap(t=>t.seats));if(state.seats.some(s=>taken.has(s))){toast('Some seats were already booked in this browser. Please choose others.');render();return;}let t={code:'SL-'+Math.random().toString(36).slice(2,8).toUpperCase(),movie:state.movie,cinema:state.cinema,date:state.date,time:state.time,seats:[...state.seats],type:state.ticketType,total:state.seats.length*fees[state.ticketType],created:new Date().toISOString(),owner:signedIn()?.email||null};saveTickets([t,...saved()]);state.lastTicket=t.code;state.seats=[];navigate('confirmation')}
function ticketHTML(t){
 const m=movies.find(m=>m.id===t.movie),cancelled=t.status==='cancelled';
 const qrPayload='STARLIGHT-DEMO|'+t.code+'|'+t.date+'|'+t.time+'|'+(t.seats||[]).join(',');
 return `<article class="digital-ticket ${cancelled?'ticket-cancelled':''}" aria-label="Digital cinema ticket"><div class="digital-ticket-head"><div><div class="eyebrow">★ STARLIGHT CINEMAS</div><h2>${esc(m?.name||t.movie)}</h2><p>${esc(m?.genre||'Cinema experience')}</p></div><span class="ticket-status">${cancelled?'CANCELLED':'DEMO TICKET'}</span></div><div class="digital-ticket-info"><div><small>CINEMA</small><strong>${esc(cinemas[t.cinema]?.name||'Cinema')}</strong></div><div><small>DATE</small><strong>${esc(t.date)}</strong></div><div><small>SHOWTIME</small><strong>${esc(t.time)}</strong></div><div><small>SEATS</small><strong>${esc((t.seats||[]).join(' · '))}</strong></div><div><small>ADMISSION</small><strong>${esc(t.type||'Standard')}</strong></div><div><small>TOTAL</small><strong>${money(Number(t.total)||0)}</strong></div></div><div class="digital-ticket-foot"><div><small>BOOKING REFERENCE</small><strong class="ticket-code">${esc(t.code)}</strong><p>Present this sample ticket only during the classroom demo.</p></div><div class="ticket-qr" data-qr="${esc(qrPayload)}" aria-label="Demo QR code for booking ${esc(t.code)}"><span>Generating demo QR…</span></div></div>${cancelled?'<div class="ticket-cancel-note">This reservation was cancelled. Its seats have been released.</div>':''}<div class="ticket-disclaimer">SAMPLE ONLY · NOT VALID FOR CINEMA ADMISSION · NO PAYMENT PROCESSED</div></article><div class="ticket-actions"><button class="btn" onclick="printDemoTicket('${esc(t.code)}')">🖨 PRINT TICKET / SAVE PDF</button><button class="btn btn-outline" onclick="printDemoReceipt('${esc(t.code)}')">PRINT RECEIPT</button></div>`;
}
function renderTicketQRCodes(){document.querySelectorAll('.ticket-qr[data-qr]').forEach(el=>{if(el.dataset.done)return;if(typeof QRCode==='undefined'){el.innerHTML='<small>QR preview needs an internet connection</small>';return}el.innerHTML='';new QRCode(el,{text:el.dataset.qr,width:122,height:122,colorDark:'#111827',colorLight:'#ffffff',correctLevel:QRCode.CorrectLevel.M});el.dataset.done='yes'})}
function demoReceiptHTML(t){return `<div class="print-receipt"><div class="eyebrow">★ STARLIGHT CINEMAS · DEMO RECEIPT</div><h2>Reservation receipt</h2><p>Reference: <strong>${esc(t.code)}</strong></p><div class="summary-row"><span>Film</span><strong>${esc(movies.find(m=>m.id===t.movie)?.name||t.movie)}</strong></div><div class="summary-row"><span>Cinema</span><strong>${esc(cinemas[t.cinema]?.name||'Cinema')}</strong></div><div class="summary-row"><span>Date &amp; time</span><strong>${esc(t.date)} ${esc(t.time)}</strong></div><div class="summary-row"><span>Seats</span><strong>${esc((t.seats||[]).join(', '))}</strong></div><div class="summary-row"><span>Ticket types</span><strong>${esc(t.type||'Standard')}</strong></div><div class="summary-row"><span>Amount (JMD)</span><strong>${money(Number(t.total)||0)}</strong></div><div class="summary-row"><span>Status</span><strong>${t.status==='cancelled'?'Cancelled':'Demo confirmed'}</strong></div><p><small>Classroom example. No payment was collected and this is not proof of purchase.</small></p></div>`}
function printDemoTicket(code){const ticket=saved().find(t=>t.code===code);if(!ticket)return toast('Ticket not found');const stage=document.getElementById('printStage');stage.innerHTML=ticketHTML(ticket);stage.querySelector('.ticket-actions')?.remove();renderTicketQRCodes();window.print()}
function printDemoReceipt(code){const ticket=saved().find(t=>t.code===code);if(!ticket)return toast('Ticket not found');document.getElementById('printStage').innerHTML=demoReceiptHTML(ticket);window.print()}
function postRenderTicketEnhancements(){if(!document.getElementById('printStage')){const stage=document.createElement('div');stage.id='printStage';stage.setAttribute('aria-hidden','true');document.body.append(stage)}renderTicketQRCodes()}

function confirmation(){let t=saved().find(t=>t.code===state.lastTicket);return hero('Booking Created!','Your sample ticket was saved locally in this browser.')+`<section class="section"><div class="wrap" style="max-width:750px"><div class="notice success">✓ Demo reservation saved successfully. No payment was made.</div>${t?ticketHTML(t):'<div class="empty">No recent booking found.</div>'}<div class="chips"><a class="btn" href="#retrieve">RETRIEVE TICKET →</a><a class="btn btn-ghost" href="#movies">EXPLORE MOVIES</a></div></div></section>`}
function retrieve(){return hero('Retrieve Your Ticket','Find your saved demo reservation using its booking reference.')+`<section class="section"><div class="wrap" style="max-width:720px"><div class="panel"><h2>Find a Booking</h2><p class="sub">Enter the booking reference issued at demo checkout, for example SL-ABC123.</p><form onsubmit="findTicket(event)" class="toolbar"><div class="field"><label>BOOKING REFERENCE</label><input id="findCode" required placeholder="SL-XXXXXX"></div><button class="btn">SEARCH TICKET →</button></form><div id="ticketResult"></div></div></div></section>`}
function findTicket(e){e.preventDefault();let code=document.getElementById('findCode').value.trim().toUpperCase(),t=saved().find(t=>t.code===code);document.getElementById('ticketResult').innerHTML=t?ticketHTML(t):'<div class="notice">No ticket was found with that code in this browser. Demo tickets are stored locally on the device used to book.</div>';postRenderTicketEnhancements()}
function profile(){const member=memberRecord(),session=signedIn();if(!member||!session)return hero('My Starlight Profile','Sign in to view your account and cinema activity.')+`<section class="section"><div class="wrap" style="max-width:690px"><div class="panel"><h2>Welcome to Starlight</h2><p class="sub">Create a demo account or sign in to view your information, movie tickets, and e-gifts.</p><div class="chips"><a href="login.html" class="btn">LOG IN</a><a href="register.html" class="btn btn-outline">REGISTER</a></div></div></div></section>`;
const tickets=saved().filter(t=>t.owner===session.email),now=new Date(),upcoming=tickets.filter(t=>t.status!=='cancelled'&&visitDate(t)>=now).sort((a,b)=>visitDate(a)-visitDate(b)),past=tickets.filter(t=>t.status==='cancelled'||visitDate(t)<now).sort((a,b)=>visitDate(b)-visitDate(a));const gifts=giftsSaved().filter(g=>g.owner===session.email),active=gifts.filter(g=>!g.redeemed),old=gifts.filter(g=>g.redeemed);
return hero('My Starlight','Your cinema story, tickets and gift cards in one place.')+`<section class="section"><div class="wrap"><div class="admin-metrics"><div class="admin-card"><strong>${upcoming.length}</strong><span>Upcoming bookings</span></div><div class="admin-card"><strong>${past.length}</strong><span>Past bookings</span></div><div class="admin-card"><strong>${active.length}</strong><span>Current e-gifts</span></div><div class="admin-card"><strong>${old.length}</strong><span>Past e-gifts</span></div></div><div class="two-col" style="align-items:start"><div><div class="panel" style="margin-bottom:22px"><div class="eyebrow">MY ACCOUNT</div><h2>Hello, ${esc(member.name)}!</h2><div class="summary-row"><span>Full name</span><strong>${esc(member.name)}</strong></div><div class="summary-row"><span>Email address</span><strong>${esc(member.email)}</strong></div><div class="summary-row"><span>Account created</span><strong>${member.created?new Date(member.created).toLocaleDateString():'Previously registered'}</strong></div><p class="sub" style="margin-top:16px">Your password is never displayed on this page.</p><button class="btn btn-outline btn-sm" onclick="logoutMember()">LOG OUT</button></div><div class="panel"><div class="eyebrow">E-GIFT WALLET</div><h2>Current E-Gifts (${active.length})</h2>${active.length?active.map(giftRow).join(''):'<div class="empty">No current e-gifts yet.</div>'}<h2 style="margin-top:26px">Past E-Gifts (${old.length})</h2>${old.length?old.map(giftRow).join(''):'<div class="empty">No redeemed demo e-gifts yet.</div>'}<a href="gifts.html" class="btn" style="margin-top:20px">CREATE AN E-GIFT →</a></div></div><div><div class="panel" style="margin-bottom:22px"><div class="eyebrow">YOUR TICKETS</div><h2>Upcoming Bookings (${upcoming.length})</h2>${upcoming.length?upcoming.map(profileTicketRow).join(''):'<div class="empty">No upcoming bookings. Your next movie night awaits!</div>'}<a href="schedule.html" class="btn" style="margin-top:20px">BOOK A MOVIE →</a></div><div class="panel"><div class="eyebrow">MOVIE MEMORIES</div><h2>Past Bookings (${past.length})</h2>${past.length?past.map(profileTicketRow).join(''):'<div class="empty">Your attended showtimes will appear here after their dates pass.</div>'}</div></div></div><p class="notice" style="margin-top:22px">Classroom demo only: account records, tickets and gifts exist in this browser, not on a secure server. Bookings made before this update or while signed out are not automatically assigned to your profile.</p></div></section>`}

function bookMovie(id,time='6:30 PM'){state.movie=id;state.time=time;state.seats=[];navigate('booking')}

let adminTab='movies';let editingMovie=null;
function admin(){let tickets=saved();return hero('Cinema Command Center','Manage demo movie listings, showtimes, trailers, and ticket prices from your browser.')+`<section class="section"><div class="wrap"><div class="notice">⚙ This is a local prototype admin dashboard, not a secure staff login. Changes are saved only in this browser. Do not store real customer information here.</div><div class="admin-metrics"><div class="admin-card"><strong>${movies.length}</strong><span>Movies listed</span></div><div class="admin-card"><strong>${tickets.length}</strong><span>Demo tickets</span></div><div class="admin-card"><strong>${money(tickets.reduce((s,t)=>s+(t.total||0),0))}</strong><span>Simulated bookings</span></div></div><div class="admin-tabs"><button class="btn ${adminTab==='movies'?'':'btn-outline'}" onclick="setAdminTab('movies')">🎬 Movies</button><button class="btn ${adminTab==='shows'?'':'btn-outline'}" onclick="setAdminTab('shows')">🕒 Showtimes</button><button class="btn ${adminTab==='pricing'?'':'btn-outline'}" onclick="setAdminTab('pricing')">🎟 Prices</button></div><div id="adminPanel">${adminContent()}</div></div></section>`}
function setAdminTab(v){adminTab=v;editingMovie=null;document.getElementById('adminPanel').innerHTML=adminContent();document.querySelectorAll('.admin-tabs button').forEach((b,i)=>b.classList.toggle('btn-outline', ['movies','shows','pricing'][i]!==v))}
function adminContent(){if(adminTab==='movies')return `<div class="admin-card"><div class="section-top"><h2>Movie Library</h2><div class="chips"><button class="btn" onclick="editMovie(null)">+ ADD MOVIE</button><button type="button" class="btn btn-outline" onclick="resetMovieCatalog()">RESET TO CODE DEFAULTS</button></div></div><div style="overflow-x:auto"><table class="admin-table"><thead><tr><th>Movie</th><th>Genre</th><th>Rating</th><th>Actions</th></tr></thead><tbody>${movies.map(m=>`<tr><td><strong>${esc(m.name)}</strong></td><td>${esc(m.genre)}</td><td>${esc(m.rating)}</td><td><button class="btn btn-sm btn-ghost" onclick="editMovie('${m.id}')">EDIT</button><button class="btn btn-sm btn-ghost" onclick="deleteMovie('${m.id}')">DELETE</button></td></tr>`).join('')}</tbody></table></div><p class="sub" style="margin-top:14px">Changes made in Admin are saved in this browser and override the movie list in js/app.js. Use Reset to Code Defaults to reload the list from your code (other bookings and gifts are not deleted).</p><div id="adminEditor"></div></div>`;
if(adminTab==='shows')return `<div class="admin-card"><h2>Manage Showtimes</h2><p class="sub">Times apply to every date and cinema in this demo. Use comma-separated formats such as 1:00 PM, 4:30 PM.</p>${movies.map(m=>`<div class="field" style="margin:16px 0"><label>${esc(m.name)}</label><input id="shows-${m.id}" value="${esc(showsFor(m).join(', '))}" placeholder="1:00 PM, 4:00 PM"></div>`).join('')}<button class="btn" onclick="saveShowtimes()">SAVE SHOWTIMES</button></div>`;
return `<div class="admin-card"><h2>Ticket Price Settings</h2><p class="sub">Example prices in Jamaican dollars.</p><div class="admin-grid">${Object.keys(fees).map(k=>`<div class="field"><label>${k.toUpperCase()}</label><input type="number" min="0" id="fee-${k}" value="${fees[k]}"></div>`).join('')}</div><button class="btn" style="margin-top:20px" onclick="saveFees()">SAVE PRICES</button></div>`}
function editMovie(id){let m=movies.find(x=>x.id===id)||{id:'',name:'',genre:'Action',rating:'PG',runtime:'1h 50m',badge:'NOW SHOWING',poster:'',tag:'',color:'#1e293b',desc:'',trailer:''};editingMovie=id;document.getElementById('adminEditor').innerHTML=`<form class="admin-card" style="margin-top:20px" onsubmit="saveMovie(event)"><h2>${id?'Edit Movie':'Add New Movie'}</h2><div class="admin-grid">${[['name','Movie Title'],['genre','Genre'],['rating','Rating'],['runtime','Runtime'],['poster','Poster URL or Local Path (images/filename.png)'],['trailer','YouTube/Vimeo Trailer URL'],['badge','Poster Badge'],['tag','Tagline'],['color','Fallback Color'],['desc','Description']].map(([key,label])=>`<div class="field ${key==='desc'?'wide':''}"><label>${label.toUpperCase()}</label>${key==='desc'?`<textarea id="edit-desc" rows="3">${esc(m.desc||'')}</textarea>`:`<input id="edit-${key}" value="${esc(m[key]||'')}" ${key==='name'?'required':''} ${key==='poster'?'placeholder="images/verity-poster.png or https://..."':key==='trailer'?'placeholder="https://youtu.be/..."':''}>`}</div>`).join('')}</div><div class="chips" style="margin-top:20px"><button class="btn" type="submit">SAVE MOVIE</button><button class="btn btn-outline" type="button" onclick="document.getElementById('adminEditor').innerHTML=''">CANCEL</button></div></form>`;document.getElementById('adminEditor').scrollIntoView({behavior:'smooth',block:'nearest'})}
function saveMovie(e){e.preventDefault();let fields=['name','genre','rating','runtime','poster','trailer','badge','tag','color','desc'];let m={};fields.forEach(k=>m[k]=document.getElementById('edit-'+k).value.trim());if(!m.name)return;if(m.poster&&!safePoster(m.poster)){toast('Poster must be a valid http(s) URL or images/filename.png');return}if(m.trailer&&!trailerEmbed(m.trailer)){toast('Please enter a YouTube or Vimeo trailer URL');return}m.id=editingMovie||'movie'+Date.now();if(editingMovie){movies=movies.map(x=>x.id===editingMovie?m:x)}else movies.push(m);try{persistAdmin()}catch(err){toast('Could not save: browser storage is blocked or full.');console.error(err);return}toast('Movie saved! Open Movies to view it.');document.getElementById('adminPanel').innerHTML=adminContent()}
function resetMovieCatalog(){if(!confirm('Replace your browser-edited movie list with the defaults in js/app.js? Your saved movie edits will be lost, but existing bookings and gifts stay.'))return;movies=JSON.parse(JSON.stringify(movieDefaults));localStorage.removeItem('starlightAdminMovies');toast('Movie list restored from code defaults');document.getElementById('adminPanel').innerHTML=adminContent()}
function deleteMovie(id){if(!confirm('Remove this movie from your demo catalog?'))return;movies=movies.filter(m=>m.id!==id);delete customShows[id];persistAdmin();toast('Movie deleted');document.getElementById('adminPanel').innerHTML=adminContent()}
function saveShowtimes(){for(const m of movies){let raw=document.getElementById('shows-'+m.id).value;let times=raw.split(',').map(s=>s.trim()).filter(Boolean);if(!times.length||times.some(s=>!/^([1-9]|1[0-2]):[0-5][0-9] (AM|PM)$/i.test(s))){toast('Use times such as 1:00 PM, 7:30 PM');return}customShows[m.id]=times}persistAdmin();toast('Showtimes updated')}
function saveFees(){for(const k of Object.keys(fees)){let n=Number(document.getElementById('fee-'+k).value);if(!Number.isFinite(n)||n<0){toast('Enter valid prices');return}fees[k]=n}persistAdmin();toast('Prices updated')}

function navigate(page){
  sessionStorage.setItem('starlightNavigationState',JSON.stringify(state));
  window.location.href=(page==='home'?'index':page)+'.html';
}
function render(){state.page=document.getElementById('app').dataset.initialPage||'home';const pages={home,movies:moviesPage,schedule,cinemas:cinemasPage,prices,events,gifts:giftPage,booking,confirmation,retrieve,profile,admin};document.getElementById('app').innerHTML=(pages[state.page]||home)();document.querySelectorAll('.nav a').forEach(a=>a.classList.toggle('active',a.dataset.page===state.page));if(window.bootstrap){const el=document.getElementById('nav');const instance=bootstrap.Collapse.getInstance(el);if(instance)instance.hide();}document.title=(state.page==='home'?'Home':state.page[0].toUpperCase()+state.page.slice(1))+' | Starlight Cinemas';window.scrollTo(0,0);postRenderTicketEnhancements()}
try { const previous=JSON.parse(sessionStorage.getItem('starlightNavigationState')||'null');
if(previous && typeof previous==='object') Object.assign(state,previous);
sessionStorage.removeItem('starlightNavigationState'); } catch(e) {}
// Route old hash-based template links to physical HTML pages.
document.addEventListener('click',function(e){
  const anchor=e.target.closest('a[href^="#"]');
  if(!anchor) return;
  const page=anchor.getAttribute('href').slice(1);
  if(['home','movies','schedule','cinemas','prices','events','gifts','booking','confirmation','retrieve','profile','admin'].includes(page)){
    e.preventDefault();navigate(page);
  }
});

// V4: Connected demo booking and operations dashboard.
// All values and customer history are stored in this browser only.
const seatRows='ABCDEF';
const demoBlocked=['A3','A4','B7','C2','C3','D8','E5','F1','F2'];
let passengerCounts={Adult:1,Child:0,Senior:0};
let adminBookingQuery='';
const bookingCount=()=>Object.values(passengerCounts).reduce((n,v)=>n+v,0);
const bookingTotal=()=>Object.entries(passengerCounts).reduce((n,[kind,num])=>n+num*(fees[kind]||0),0);
function isActiveTicket(t){return t.status!=='cancelled'}
function bookedSeats(){return new Set(saved().filter(t=>isActiveTicket(t)&&t.movie===state.movie&&+t.cinema===+state.cinema&&t.date===state.date&&t.time===state.time).flatMap(t=>t.seats||[]))}
function seatSelectionAvailable(){const sold=bookedSeats();return state.seats.every(seat=>!sold.has(seat)&&!demoBlocked.includes(seat))}
function setBookingCinema(value){state.cinema=+value;state.seats=[];render()}
function setBookingDate(value){state.date=value;state.seats=[];render()}
function setBookingTime(value){state.time=value;state.seats=[];render()}
function adjustPassengers(kind,delta){let next=passengerCounts[kind]+delta;if(next<0||next>8)return;let proposed=bookingCount()+delta;if(proposed<1||proposed>8){toast('Choose between 1 and 8 tickets per booking.');return}passengerCounts[kind]=next;if(state.seats.length>proposed)state.seats=state.seats.slice(0,proposed);renderBookingContents()}
function renderBookingContents(){const el=document.getElementById('app');if(el&&el.dataset.initialPage==='booking')el.innerHTML=booking();}
booking=function(){
 const m=movies.find(x=>x.id===state.movie)||movies[0];if(!m)return hero('No movies available','Please ask the cinema administrator to add a film.');
 state.movie=m.id;if(!showsFor(m).includes(state.time))state.time=showsFor(m)[0]||'6:30 PM';
 const occupied=bookedSeats(); const count=bookingCount(); const price=bookingTotal();
 const seats=[...seatRows].map((row,rowIndex)=>`<div class="seat-row"><span class="seat-letter">${row}</span><div class="seat-row-buttons">${Array.from({length:10},(_,i)=>{let id=row+(i+1);let blocked=demoBlocked.includes(id)||occupied.has(id);return `<button type="button" aria-label="Seat ${id}${blocked?' unavailable':''}" aria-pressed="${state.seats.includes(id)}" class="seat ${blocked?'taken':''} ${state.seats.includes(id)?'selected':''} ${i===5?'aisle-gap':''}" ${blocked?'disabled':''} onclick="toggleSeat('${id}')">${i+1}</button>`}).join('')}</div></div>`).join('');
 return hero('Choose Your Seats','Select your screening, ticket types and seats. All bookings shown here are demonstrations.')+`<section class="section"><div class="wrap booking-layout"><div class="panel booking-panel"><div class="eyebrow">STEP 1 OF 3 · SCREENING</div><h2>${esc(m.name)}</h2><div class="booking-controls"><div class="field"><label>CINEMA</label><select onchange="setBookingCinema(this.value)">${cinemas.map((c,i)=>`<option value="${i}" ${state.cinema===i?'selected':''}>${esc(c.name)}</option>`).join('')}</select></div><div class="field"><label>DATE</label><select onchange="setBookingDate(this.value)">${dateOptions()}</select></div><div class="field"><label>TIME</label><select onchange="setBookingTime(this.value)">${showsFor(m).map(t=>`<option ${state.time===t?'selected':''}>${esc(t)}</option>`).join('')}</select></div></div><div class="eyebrow" style="margin-top:28px">STEP 2 OF 3 · TICKETS</div><h3>Who's coming?</h3><div class="passenger-grid">${Object.keys(fees).map(kind=>`<div class="passenger"><div><strong>${kind}</strong><small>${money(fees[kind])} / ticket</small></div><div class="counter"><button type="button" aria-label="Remove ${kind}" onclick="adjustPassengers('${kind}',-1)">−</button><strong>${passengerCounts[kind]}</strong><button type="button" aria-label="Add ${kind}" onclick="adjustPassengers('${kind}',1)">+</button></div></div>`).join('')}</div><div class="eyebrow" style="margin-top:30px">STEP 3 OF 3 · SEATS</div><h3>Choose ${count} seat${count===1?'':'s'}</h3><p class="sub">${state.seats.length} of ${count} selected. Screen is at the top. Maximum 8 tickets per booking.</p><div class="cinema-room"><div class="screen">SCREEN THIS WAY</div><div class="seatmap-v4">${seats}</div><div class="legend"><span><i class="dot"></i> Available</span><span><i class="dot" style="background:var(--gold)"></i> Selected</span><span><i class="dot" style="background:#303848"></i> Unavailable</span></div></div></div><aside class="panel booking-summary"><div class="eyebrow">YOUR RESERVATION</div><h2>Booking Summary</h2><div class="summary-row"><span>Film</span><strong>${esc(m.name)}</strong></div><div class="summary-row"><span>Location</span><strong>${esc(cinemas[state.cinema].name)}</strong></div><div class="summary-row"><span>Screening</span><strong>${esc(state.date)}<br>${esc(state.time)}</strong></div>${Object.entries(passengerCounts).filter(([,q])=>q>0).map(([kind,q])=>`<div class="summary-row"><span>${kind} × ${q}</span><strong>${money(q*fees[kind])}</strong></div>`).join('')}<div class="summary-row"><span>Selected seats</span><strong>${esc(state.seats.join(', ')||'None yet')}</strong></div><div class="summary-row"><span>Total</span><strong class="summary-total">${money(price)}</strong></div><button class="btn" style="width:100%;margin:20px 0 12px" onclick="checkout()" ${state.seats.length!==count?'disabled':''}>CONFIRM DEMO BOOKING →</button><p class="sub" style="font-size:12px">No money is charged. Reservations are saved in this browser. Sign in first if you want tickets to appear in your profile.</p><a href="login.html" style="display:${signedIn()?'none':'inline-block'};color:var(--gold)">Sign in to save to My Profile →</a></aside></div></section>`;
};
toggleSeat=function(id){if(state.seats.includes(id)){state.seats=state.seats.filter(x=>x!==id)}else{if(state.seats.length>=bookingCount()){toast(`You selected ${bookingCount()} tickets. Increase your ticket count to choose more seats.`);return}if(bookedSeats().has(id)||demoBlocked.includes(id))return;state.seats.push(id)}renderBookingContents()};
checkout=function(){const count=bookingCount();if(state.seats.length!==count){toast('Choose one seat per ticket.');return}if(state.date<todayISO()){toast('Choose a future screening date.');return}if(!seatSelectionAvailable()){toast('A seat is unavailable. Please choose a different one.');render();return}const t={code:'SL-'+Math.random().toString(36).slice(2,10).toUpperCase(),movie:state.movie,cinema:state.cinema,date:state.date,time:state.time,seats:[...state.seats],type:Object.keys(passengerCounts).filter(k=>passengerCounts[k]).map(k=>`${passengerCounts[k]} ${k}`).join(', '),ticketTypes:{...passengerCounts},total:bookingTotal(),created:new Date().toISOString(),owner:signedIn()?.email||null,status:'confirmed'};saveTickets([t,...saved()]);state.lastTicket=t.code;state.seats=[];passengerCounts={Adult:1,Child:0,Senior:0};navigate('confirmation')};
const legacyAdmin=admin,legacyAdminContent=adminContent;
admin=function(){const t=saved(),active=t.filter(isActiveTicket),cancelled=t.length-active.length;let html=legacyAdmin();html=html.replace('🎟 Prices</button></div>',`🎟 Prices</button><button class="btn ${adminTab==='bookings'?'':'btn-outline'}" onclick="setAdminTab('bookings')">📋 Bookings</button></div>`);html=html.replace('⚙ This is a local prototype admin dashboard', '⚙ Demo-only operations: this page is not access-controlled. This is a local prototype admin dashboard');html=html.replace('<div class="admin-tabs">',`<div class="admin-card admin-insight"><h3>Booking snapshot</h3><p class="sub">${active.length} confirmed · ${cancelled} cancelled · ${active.reduce((a,b)=>a+(b.seats?.length||0),0)} seats reserved</p></div><div class="admin-tabs">`);return html};
adminContent=function(){if(adminTab!=='bookings')return legacyAdminContent();const records=saved().filter(t=>!adminBookingQuery||[t.code,t.owner,t.movie,cinemas[t.cinema]?.name].join(' ').toLowerCase().includes(adminBookingQuery.toLowerCase()));return `<div class="admin-card"><div class="section-top"><div><h2>Booking Management</h2><p class="sub">Local demo reservations; cancelling a booking releases its seats.</p></div><button class="btn btn-outline btn-sm" onclick="exportDemoBookings()">EXPORT CSV</button></div><div class="field" style="margin:15px 0"><label>SEARCH BOOKINGS</label><input placeholder="Reference, customer email, movie or cinema" value="${esc(adminBookingQuery)}" oninput="searchAdminBookings(this.value)"></div><div id="adminBookingTable">${adminBookingTable(records)}</div></div>`};
function adminBookingTable(records){return `<div style="overflow-x:auto"><table class="admin-table"><thead><tr><th>Reference</th><th>Movie / Screening</th><th>Customer</th><th>Seats</th><th>Value</th><th>Status</th><th>Action</th></tr></thead><tbody>${records.map(t=>`<tr><td>${esc(t.code)}</td><td><strong>${esc(movies.find(m=>m.id===t.movie)?.name||t.movie)}</strong><br><small>${esc(t.date)} · ${esc(t.time)}<br>${esc(cinemas[t.cinema]?.name||'')}</small></td><td>${esc(t.owner||'Guest')}</td><td>${esc((t.seats||[]).join(', '))}</td><td>${money(+t.total||0)}</td><td><span class="status-pill ${isActiveTicket(t)?'status-ok':'status-off'}">${isActiveTicket(t)?'Confirmed':'Cancelled'}</span></td><td>${isActiveTicket(t)?`<button class="btn btn-sm btn-outline" onclick="cancelDemoBooking('${esc(t.code)}')">Cancel</button>`:'—'}</td></tr>`).join('')||'<tr><td colspan="7">No matching bookings.</td></tr>'}</tbody></table></div>`};
function searchAdminBookings(value){adminBookingQuery=value;const matches=saved().filter(t=>!value||[t.code,t.owner,t.movie,cinemas[t.cinema]?.name].join(' ').toLowerCase().includes(value.toLowerCase()));document.getElementById('adminBookingTable').innerHTML=adminBookingTable(matches)}
function cancelDemoBooking(code){if(!confirm('Cancel this demo reservation? Its seats will become available again.'))return;const all=saved(),record=all.find(t=>t.code===code);if(!record||!isActiveTicket(record))return;record.status='cancelled';record.cancelledAt=new Date().toISOString();saveTickets(all);toast('Reservation cancelled; seats released');render()}
function exportDemoBookings(){const rows=[['Reference','Movie','Cinema','Date','Time','Customer','Seats','Ticket Types','Total JMD','Status'],...saved().map(t=>[t.code,movies.find(m=>m.id===t.movie)?.name||t.movie,cinemas[t.cinema]?.name||'',t.date,t.time,t.owner||'Guest',(t.seats||[]).join(' '),t.type,t.total,isActiveTicket(t)?'Confirmed':'Cancelled'])];const csv=rows.map(row=>row.map(v=>'"'+String(v??'').replace(/"/g,'""')+'"').join(',')).join('\r\n');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));a.download='starlight-demo-bookings.csv';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
setAdminTab=function(v){adminTab=v;editingMovie=null;document.getElementById('adminPanel').innerHTML=adminContent();document.querySelectorAll('.admin-tabs button').forEach((b,i)=>b.classList.toggle('btn-outline',['movies','shows','pricing','bookings'][i]!==v))};

render();

// Decorative loading screen and viewport animation, with reduced-motion support.
function enhanceMotion(root=document){if(window.matchMedia('(prefers-reduced-motion: reduce)').matches)return;root.querySelectorAll('.movie,.panel,.show-card,.location-card,.price-card,.section-top,.banner').forEach(el=>{if(el.dataset.reveal)return;el.dataset.reveal='1';el.classList.add('cinema-reveal');cinemaObserver?.observe(el)})}
const cinemaObserver=typeof IntersectionObserver==='undefined'?null:new IntersectionObserver(entries=>{entries.forEach(e=>{if(e.isIntersecting){e.target.classList.add('cinema-visible');cinemaObserver.unobserve(e.target)}})},{threshold:0.08});
const cinemaApp=document.getElementById('app');if(cinemaApp){const cinemaChanges=new MutationObserver(()=>{if(cinemaApp.dataset.initialPage==='movies'&&!document.getElementById('discoverCount')?.textContent)renderDiscovery();enhanceMotion(cinemaApp)});cinemaChanges.observe(cinemaApp,{childList:true,subtree:false});if(cinemaApp.dataset.initialPage==='movies')renderDiscovery();enhanceMotion(cinemaApp)}
window.addEventListener('load',()=>{const loader=document.getElementById('cinemaLoader');if(!loader)return;window.setTimeout(()=>{loader.classList.add('loader-finished');window.setTimeout(()=>loader.remove(),450)},350)},{once:true});

// Coursework integration: jQuery event delegation and DOM updates for movie search.
// Because pages are rendered dynamically, this delegated handler survives re-renders.
if (window.jQuery) {
  jQuery(document).on('input', '#discoverQuery', function () {
    discovery.query = jQuery(this).val();
    renderDiscovery();
    jQuery('#discoverCount').attr('data-filter-active', discovery.query ? 'true' : 'false');
  });
}
// Bootstrap modal showing a movie's existing information.
document.addEventListener('click', function (event) {
  const trigger = event.target.closest('.movie-details');
  if (!trigger || !window.bootstrap) return;
  const movie = movies.find(m => m.id === trigger.dataset.movieId);
  if (!movie) return;
  document.getElementById('movieDetailsTitle').textContent = movie.name;
  document.getElementById('movieDetailsBody').innerHTML = `<p><strong>Genre:</strong> ${esc(movie.genre)}</p><p><strong>Rating:</strong> ${esc(movie.rating)}</p><p><strong>Runtime:</strong> ${esc(movie.runtime)}</p><p>${esc(movie.desc || 'More details coming soon.')}</p>`;
  bootstrap.Modal.getOrCreateInstance(document.getElementById('movieDetailsModal')).show();
});
